import roundSplit from "../../ml/playoff_round_split.json";

/** Pooled expanding-window evaluation, generated by ml/train_series_model.py. */
export const PLAYOFF_MODEL_EVAL = Object.freeze({
  folds: roundSplit.evaluation.folds,
  series: roundSplit.pooled.n,
  firstSeason: roundSplit.evaluation.firstSeason,
});

/** Both calibration losses are lower-is-better; the baseline uses the training home-court rate. */
export const PLAYOFF_MODEL_CALIBRATION = Object.freeze([
  { key: "logLoss", label: "LOG LOSS", model: roundSplit.pooled.logLoss, baseline: roundSplit.pooled.baselineLogLoss },
  { key: "brier", label: "BRIER SCORE", model: roundSplit.pooled.brier, baseline: roundSplit.pooled.baselineBrier },
].map((metric) => Object.freeze({
  ...metric,
  improvementPct: Math.round(100 * (metric.baseline - metric.model) / metric.baseline),
})));

/** Accuracy remains published alongside calibration, including each season's paired record. */
export const PLAYOFF_MODEL_ACCURACY = Object.freeze({
  model: roundSplit.pooled.accuracy / 100,
  baseline: roundSplit.pooled.baselineAccuracy / 100,
  baselineName: "always predict the home-court team",
  winTieLoss: `${roundSplit.pooledRecord.win}/${roundSplit.pooledRecord.tie}/${roundSplit.pooledRecord.loss}`,
});
